"use client";

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, Clock, CheckCircle, AlertCircle, XCircle } from "lucide-react";
import Link from "next/link";
import { ComplaintModal } from "@/components/complaint-modal";
import { UpdateComplaintModal } from "@/components/update-complaint-modal";

const complaints = [
  {
    id: "C001",
    title: "Water leakage in bathroom",
    category: "Maintenance",
    status: "In Progress",
    priority: "High",
    date: "2024-08-05",
    description:
      "There is a water leakage from the ceiling in the master bathroom.",
  },
  {
    id: "C002",
    title: "Noise complaint from upstairs neighbor",
    category: "Neighbor Issue",
    status: "Resolved",
    priority: "Medium",
    date: "2024-08-03",
    description: "Excessive noise during late hours from the apartment above.",
  },
  {
    id: "C003",
    title: "Elevator not working properly",
    category: "Common Area",
    status: "Pending",
    priority: "High",
    date: "2024-08-07",
    description: "The elevator makes strange noises and stops between floors.",
  },
];

const getStatusIcon = (status: string) => {
  switch (status) {
    case "Pending":
      return <Clock className="w-4 h-4" />;
    case "In Progress":
      return <AlertCircle className="w-4 h-4" />;
    case "Resolved":
      return <CheckCircle className="w-4 h-4" />;
    case "Rejected":
      return <XCircle className="w-4 h-4" />;
    default:
      return <Clock className="w-4 h-4" />;
  }
};

const getStatusColor = (status: string) => {
  switch (status) {
    case "Pending":
      return "bg-yellow-100 text-yellow-800";
    case "In Progress":
      return "bg-blue-100 text-blue-800";
    case "Resolved":
      return "bg-green-100 text-green-800";
    case "Rejected":
      return "bg-red-100 text-red-800";
    default:
      return "bg-gray-100 text-gray-800";
  }
};

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case "High":
      return "bg-red-100 text-red-800";
    case "Medium":
      return "bg-yellow-100 text-yellow-800";
    case "Low":
      return "bg-green-100 text-green-800";
    default:
      return "bg-gray-100 text-gray-800";
  }
};

export default function ComplaintsPage() {
  const [selectedTab, setSelectedTab] = useState("all");
  const [selectedComplaint, setSelectedComplaint] = useState(null);
  const [updateComplaint, setUpdateComplaint] = useState(null);

  const filteredComplaints = complaints.filter((complaint) => {
    if (selectedTab === "all") return true;
    return complaint.status.toLowerCase().replace(" ", "-") === selectedTab;
  });

  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Complaints</h1>
          <p className="text-gray-600">Manage and track your complaints</p>
        </div>
        <Link href="/complaints/new">
          <Button>
            <Plus className="w-4 h-4 mr-2" />
            New Complaint
          </Button>
        </Link>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Total</p>
                <p className="text-2xl font-bold">{complaints.length}</p>
              </div>
              <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                <AlertCircle className="w-4 h-4 text-blue-600" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Pending</p>
                <p className="text-2xl font-bold">
                  {complaints.filter((c) => c.status === "Pending").length}
                </p>
              </div>
              <div className="w-8 h-8 bg-yellow-100 rounded-full flex items-center justify-center">
                <Clock className="w-4 h-4 text-yellow-600" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">In Progress</p>
                <p className="text-2xl font-bold">
                  {complaints.filter((c) => c.status === "In Progress").length}
                </p>
              </div>
              <div className="w-8 h-8 bg-blue-100 rounded-full flex items-center justify-center">
                <AlertCircle className="w-4 h-4 text-blue-600" />
              </div>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Resolved</p>
                <p className="text-2xl font-bold">
                  {complaints.filter((c) => c.status === "Resolved").length}
                </p>
              </div>
              <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center">
                <CheckCircle className="w-4 h-4 text-green-600" />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Tabs
        value={selectedTab}
        onValueChange={setSelectedTab}
        className="space-y-4"
      >
        <TabsList>
          <TabsTrigger value="all">All</TabsTrigger>
          <TabsTrigger value="pending">Pending</TabsTrigger>
          <TabsTrigger value="in-progress">In Progress</TabsTrigger>
          <TabsTrigger value="resolved">Resolved</TabsTrigger>
        </TabsList>

        <TabsContent value={selectedTab} className="space-y-4">
          {filteredComplaints.map((complaint) => (
            <Card key={complaint.id}>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <CardTitle className="text-lg">{complaint.title}</CardTitle>
                    <Badge
                      variant="outline"
                      className={getStatusColor(complaint.status)}
                    >
                      <div className="flex items-center gap-1">
                        {getStatusIcon(complaint.status)}
                        {complaint.status}
                      </div>
                    </Badge>
                    <Badge
                      variant="outline"
                      className={getPriorityColor(complaint.priority)}
                    >
                      {complaint.priority}
                    </Badge>
                  </div>
                  <div className="text-sm text-gray-500">
                    ID: {complaint.id}
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <div className="flex items-center gap-4 text-sm text-gray-600">
                    <span>Category: {complaint.category}</span>
                    <span>Date: {complaint.date}</span>
                  </div>
                  <p className="text-gray-700">{complaint.description}</p>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => setSelectedComplaint(complaint)}
                    >
                      View Details
                    </Button>
                    {complaint.status !== "Resolved" && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setUpdateComplaint(complaint)}
                      >
                        Update
                      </Button>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </TabsContent>
      </Tabs>
      {selectedComplaint && (
        <ComplaintModal
          complaint={selectedComplaint}
          onClose={() => setSelectedComplaint(null)}
        />
      )}

      {updateComplaint && (
        <UpdateComplaintModal
          complaint={updateComplaint}
          onClose={() => setUpdateComplaint(null)}
          onUpdate={(updatedComplaint) => {
            // Update the complaint in the list
            console.log(updatedComplaint);
            setUpdateComplaint(null);
          }}
        />
      )}
    </div>
  );
}
